import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests',
  timeout: 30000,
  expect: { timeout: 5000 },
  fullyParallel: true,
  retries: 1,
  reporter: [['html', { open: 'never' }], ['list']],
  use: {
    baseURL: 'https://app.example.com',
    trace: 'on-first-retry',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    viewport: { width: 1280, height: 800 }
  },
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
    { name: 'firefox', use: { ...devices['Desktop Firefox'] } },
    { name: 'webkit', use: { ...devices['Desktop Safari'] } }
  ]
});

{
  "name": "testlogin_video_automated_flow-playwright-ts",
  "version": "1.0.0",
  "description": "Playwright TypeScript POM Automation Suite for Testlogin video Automated Flow",
  "scripts": {
    "test": "playwright test",
    "test:headed": "playwright test --headed",
    "test:ui": "playwright test --ui",
    "report": "playwright show-report"
  },
  "devDependencies": {
    "@playwright/test": "^1.42.1",
    "@types/node": "^20.11.24",
    "typescript": "^5.4.2"
  }
}

import { Page, Locator, expect } from '@playwright/test';

export abstract class BasePage {
  readonly page: Page;

  constructor(page: Page) {
    this.page = page;
  }

  async goto(url: string = ''): Promise<void> {
    await this.page.goto(url);
    await this.page.waitForLoadState('domcontentloaded');
  }

  async clickElement(locator: Locator, timeout: number = 8000): Promise<void> {
    await locator.waitFor({ state: 'visible', timeout });
    await locator.click();
  }

  async fillElement(locator: Locator, text: string, timeout: number = 8000): Promise<void> {
    await locator.waitFor({ state: 'visible', timeout });
    await locator.fill(text);
  }

  async selectOption(locator: Locator, option: string): Promise<void> {
    await locator.waitFor({ state: 'visible', timeout: 8000 });
    await locator.selectOption(option);
  }

  async verifyVisible(locator: Locator, timeout: number = 8000): Promise<void> {
    await expect(locator).toBeVisible({ timeout });
  }
}

import { Page, Locator } from '@playwright/test';
import { BasePage } from './BasePage';

export class LandingAuthenticationPagePage extends BasePage {
  readonly pageUrl: string = 'https://app.example.com';
  readonly application_home_page: Locator;
  readonly username___mobile_number_field: Locator;
  readonly password_field: Locator;
  readonly login_to_dashboard_button: Locator;

  constructor(page: Page) {
    super(page);
    this.application_home_page = this.page.goto('https://app.example.com');
    this.username___mobile_number_field = this.page.getByRole('textbox', { name: 'username' });
    this.password_field = this.page.getByRole('textbox', { name: 'password' });
    this.login_to_dashboard_button = this.page.getByText('Login to Dashboard', { exact: true });
  }

  async navigate(): Promise<void> {
    await this.goto(this.pageUrl);
  }

  async verify_application_home_page(): Promise<void> {
    await this.verifyVisible(this.application_home_page);
  }

  async fill_username___mobile_number_field(value: string = '9876543210'): Promise<void> {
    await this.fillElement(this.username___mobile_number_field, value);
  }

  async fill_password_field(value: string = 'SecretPassword123!'): Promise<void> {
    await this.fillElement(this.password_field, value);
  }

  async click_login_to_dashboard_button(): Promise<void> {
    await this.clickElement(this.login_to_dashboard_button);
  }
}

import { Page, Locator } from '@playwright/test';
import { BasePage } from './BasePage';

export class ApplicationDashboardNavigationPage extends BasePage {
  readonly pageUrl: string = 'https://app.example.com/dashboard';
  readonly main_module_navigation_menu: Locator;

  constructor(page: Page) {
    super(page);
    this.main_module_navigation_menu = this.page.getByText('Management', { exact: true });
  }

  async navigate(): Promise<void> {
    await this.goto(this.pageUrl);
  }

  async click_main_module_navigation_menu(): Promise<void> {
    await this.clickElement(this.main_module_navigation_menu);
  }
}

import { Page, Locator } from '@playwright/test';
import { BasePage } from './BasePage';

export class WorkflowDetailsActionViewPage extends BasePage {
  readonly pageUrl: string = 'https://app.example.com/manage';
  readonly action_trigger_button: Locator;
  readonly workflow_verification_view: Locator;

  constructor(page: Page) {
    super(page);
    this.action_trigger_button = this.page.getByText('Add New', { exact: true });
    this.workflow_verification_view = this.page.getByText('Success', { exact: true });
  }

  async navigate(): Promise<void> {
    await this.goto(this.pageUrl);
  }

  async click_action_trigger_button(): Promise<void> {
    await this.clickElement(this.action_trigger_button);
  }

  async verify_workflow_verification_view(): Promise<void> {
    await this.verifyVisible(this.workflow_verification_view);
  }
}

import { test, expect } from '@playwright/test';
import { LandingAuthenticationPagePage } from '../pages/LandingAuthenticationPagePage';
import { ApplicationDashboardNavigationPage } from '../pages/ApplicationDashboardNavigationPage';
import { WorkflowDetailsActionViewPage } from '../pages/WorkflowDetailsActionViewPage';

test.describe('Testlogin video Automated Flow - Playwright TypeScript Suite', () => {
  test('executes all verified sequential steps from walkthrough video', async ({ page }) => {
    const landingauthenticationpagePage = new LandingAuthenticationPagePage(page);
    const applicationdashboardnavigationPage = new ApplicationDashboardNavigationPage(page);
    const workflowdetailsactionviewPage = new WorkflowDetailsActionViewPage(page);

    // Navigate to initial application URL
    await landingauthenticationpagePage.navigate();

    // Step 1: Verify Application Home Page
    await landingauthenticationpagePage.verify_application_home_page();

    // Step 2: Fill Username / Mobile Number Field
    await landingauthenticationpagePage.fill_username___mobile_number_field('9876543210');

    // Step 3: Fill Password Field
    await landingauthenticationpagePage.fill_password_field('SecretPassword123!');

    // Step 4: Click Login to Dashboard Button
    await landingauthenticationpagePage.click_login_to_dashboard_button();

    // Step 5: Click Main Module Navigation Menu
    await applicationdashboardnavigationPage.click_main_module_navigation_menu();

    // Step 6: Click Action Trigger Button
    await workflowdetailsactionviewPage.click_action_trigger_button();

    // Step 7: Verify Workflow Verification View
    await workflowdetailsactionviewPage.verify_workflow_verification_view();

    // Verification check
    await expect(page).not.toHaveURL(/error/i);
  });
});

