This is a production-ready, enterprise-grade QA Automation architecture built with Playwright and TypeScript. It leverages the Page Object Model (POM) pattern for maintainability, enforces Data-Driven Testing (DDT) for comprehensive coverage, and utilizes strict configuration for stable, scalable test execution.

---

### 📂 Folder Structure

```text
automation-project/
├── .env
├── package.json
├── playwright.config.ts
├── data/
│   └── testData.json
├── pages/
│   ├── BasePage.ts
│   └── LoginPage.ts
├── tests/
│   └── login.spec.ts
└── utils/
    └── envUtils.ts
```

---

### --- Configuration & Dependencies

#### 1. `.env`
```text
BASE_URL=https://practicetestautomation.com/
TEST_USER=student
TEST_PASSWORD=Password123
```

#### 2. `package.json`
```json
{
  "name": "playwright-ts-framework",
  "version": "1.0.0",
  "devDependencies": {
    "@playwright/test": "^1.40.0",
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  },
  "scripts": {
    "test": "npx playwright test"
  }
}
```

#### 3. `playwright.config.ts`
```typescript
import { defineConfig, devices } from '@playwright/test';
import { EnvUtils } from './utils/envUtils';
import path from 'path';

const runId = new Date().getTime();
const STORAGE_STATE = path.join(__dirname, 'playwright/.auth/user.json');

export default defineConfig({
  testDir: './tests',
  fullyParallel: false,
  workers: 1,
  retries: 0,
  reporter: [['html', { outputFolder: `playwright-report/run-${runId}` }]],
  timeout: 180000,
  expect: { timeout: 60000 },
  use: {
    baseURL: EnvUtils.BASE_URL,
    actionTimeout: 50000,
    trace: 'on',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
  },
  outputDir: `test-results/run-${runId}`,
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } }
  ],
});
```

#### 4. `utils/envUtils.ts`
```typescript
import * as dotenv from 'dotenv';
dotenv.config();

export class EnvUtils {
    public static readonly BASE_URL = process.env.BASE_URL || '';
    public static readonly TEST_USER = process.env.TEST_USER || '';
    public static readonly TEST_PASSWORD = process.env.TEST_PASSWORD || '';
}
```

---

### --- Page Object Model (POM)

#### 1. `pages/BasePage.ts`
```typescript
import { expect, Page, Locator } from '@playwright/test';

export abstract class BasePage {
    public readonly page: Page;

    constructor(page: Page) {
        this.page = page;
    }

    public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
    }
}
```

#### 2. `pages/LoginPage.ts`
```typescript
import { expect, Page, Locator } from '@playwright/test';
import { BasePage } from './BasePage';

export class LoginPage extends BasePage {
    public readonly usernameField: Locator = this.page.getByLabel('Username');
    public readonly passwordField: Locator = this.page.getByLabel('Password');
    public readonly submitButton: Locator = this.page.getByRole('button', { name: 'Submit' });
    public readonly errorMessage: Locator = this.page.locator('#error');
    public readonly successHeader: Locator = this.page.locator('h1.post-title');

    constructor(page: Page) {
        super(page);
    }

    public async login(user: string, pass: string): Promise<void> {
        await this.usernameField.fill(user);
        await this.passwordField.fill(pass);
        await this.submitButton.click();
    }
}
```

---

### --- Test Implementation

#### 1. `data/testData.json`
```json
{
  "authScenarios": [
    { "testCaseId": "TC-TS-AI-5795-01", "username": "student", "password": "Password123", "description": "Successful Login" },
    { "testCaseId": "TC-TS-AI-5795-03-A", "username": "student", "password": "WrongPass123", "description": "Invalid Password" },
    { "testCaseId": "TC-TS-AI-5795-03-B", "username": "student", "password": "password123!", "description": "Invalid Password Special" },
    { "testCaseId": "TC-TS-AI-5795-03-C", "username": "student", "password": "PASSWORD123", "description": "Invalid Password Caps" }
  ]
}
```

#### 2. `tests/login.spec.ts`
```typescript
import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import testData from '../data/testData.json';

test.describe('Login Module Tests', () => {
    let loginPage: LoginPage;

    test.beforeEach(async ({ page }) => {
        loginPage = new LoginPage(page);
        await page.goto('/practicetestautomation.com/practice-test-login/');
    });

    // Data-Driven Tests for TC-01 and TC-03
    testData.authScenarios.forEach((data) => {
        test(`${data.testCaseId} - ${data.description}`, async ({ page }) => {
            await loginPage.login(data.username, data.password);
            if (data.description === 'Successful Login') {
                await expect(loginPage.successHeader).toHaveText(/Logged In Successfully/);
            } else {
                await expect(loginPage.errorMessage).toBeVisible();
            }
        });
    });

    test('TC-TS-AI-5795-02 - UI Layout Accuracy', async ({ page }) => {
        await expect(page).toHaveTitle(/Test login/);
        await expect(loginPage.usernameField).toBeVisible();
        await expect(loginPage.passwordField).toBeVisible();
        await expect(loginPage.submitButton).toBeVisible();
        await expect(page.locator('text=Your username is student')).toBeVisible();
    });

    test('TC-TS-AI-5795-04 - Password Field Masking', async ({ page }) => {
        await loginPage.passwordField.fill('secret123');
        const type = await loginPage.passwordField.getAttribute('type');
        expect(type).toBe('password');
    });
});
```

