import { expect, Locator, Page } from '@playwright/test';

/**
 * Abstract Base Page class providing core framework helpers,
 * reusable explicit waits, and architectural typing setups.
 */
export abstract class BasePage {
  public readonly page: Page;

  constructor(page: Page) {
    this.page = page;
  }

  /**
   * Safe click implementation with high trace visibility
   */
  public async click(locator: Locator): Promise<void> {
    await locator.waitFor({ state: 'visible' });
    await locator.click();
  }

  /**
   * Input filling wrapper replacing the legacy type() API
   */
  public async fillInput(locator: Locator, text: string): Promise<void> {
    await locator.waitFor({ state: 'visible' });
    await locator.clear();
    await locator.fill(text);
  }

  /**
   * Safely fetches trimmed text contents from a locator
   */
  public async getText(locator: Locator): Promise<string> {
    const text = await locator.textContent();
    return text ? text.trim() : '';
  }

  /**
   * Custom Wait for UI Component Stability utilizing standard Playwright assertions
   */
  public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
    await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
  }

  /**
   * Evaluates if any loader states or network spinners are visible
   */
  public async waitForElementToDetach(locator: Locator, timeout?: number): Promise<void> {
    await locator.waitFor({ state: 'detached', timeout: timeout ?? 15000 });
  }
}
```

