import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

export class PaginationPage extends BasePage {
  // Locators defined strictly under priority rules
  public readonly nextButton: Locator;
  public readonly previousButton: Locator;
  public readonly activePageIndicator: Locator;
  public readonly loadingOverlay: Locator;
  public readonly gridRows: Locator;

  constructor(page: Page) {
    super(page);
    this.nextButton = page.getByRole('button', { name: 'Next' });
    this.previousButton = page.getByRole('button', { name: 'Previous' });
    this.activePageIndicator = page.getByTestId('active-page-number');
    this.loadingOverlay = page.locator('.data-grid-spinner, [data-testid="loading-state"]');
    this.gridRows = page.locator('.data-grid-row');
  }

  /**
   * Navigates to the pagination dashboard sandbox
   */
  public async navigateToPaginationGrid(): Promise<void> {
    await this.page.goto('');
    await this.page.waitForLoadState('domcontentloaded');
  }

  /**
   * Perform sequential next page clicks with precise API micro-throttles
   */
  public async clickNextSequentially(clickCount: number, throttleMs: number): Promise<void> {
    for (let i = 0; i < clickCount; i++) {
      await this.nextButton.click();
      if (throttleMs > 0) {
        await this.page.waitForTimeout(throttleMs);
      }
    }
  }

  /**
   * Execute multiple simultaneous clicks asynchronously to emulate network race triggers
   */
  public async clickNextConcurrently(burstCount: number): Promise<void> {
    const clickPromises: Promise<void>[] = [];
    for (let i = 0; i < burstCount; i++) {
      clickPromises.push(this.nextButton.click({ force: true }));
    }
    await Promise.all(clickPromises);
  }

  /**
   * Simulates setting specific UI/Network properties via query parameters or Mocking
   */
  public async setInitialPageState(startPage: number, totalPages: number): Promise<void> {
    await this.page.evaluate(({ start, total }) => {
      // Mocking global window variables inside test app context if available
      if ((window as any).setPaginationState) {
        (window as any).setPaginationState(start, total);
      }
    }, { start: startPage, total: totalPages });

    // Fallback/direct navigation to handle configuration parameterization dynamically
    const currentUrl = this.page.url();
    const separator = currentUrl.includes('?') ? '&' : '?';
    await this.page.goto(`${currentUrl}${separator}page=${startPage}&total=${totalPages}`);
    await this.page.waitForLoadState('networkidle');
  }

  /**
   * Fetches the actual current page number as a number
   */
  public async getCurrentPageNumber(): Promise<number> {
    await this.page.waitForLoadState('domcontentloaded');
    const pageNumText = await this.getText(this.activePageIndicator);
    return parseInt(pageNumText || '1', 10);
  }

  /**
   * Verifies if the active page indicator displays the expected page
   */
  public async assertActivePage(expectedPage: number): Promise<void> {
    await expect(this.activePageIndicator).toHaveText(expectedPage.toString(), { timeout: 10000 });
  }

  /**
   * Subscribes to API requests and count outward navigation requests
   * for strict validation of debounce mechanisms.
   */
  public trackPaginationRequests(): { getRequestCount: () => number } {
    let requestCount = 0;
    this.page.on('request', (request) => {
      if (request.url().includes('/api/items') || request.url().includes('pagination')) {
        requestCount++;
      }
    });
    return {
      getRequestCount: () => requestCount
    };
  }
}
