This is a production-ready, scalable, and maintainable QA Automation framework built with Playwright and TypeScript. It utilizes the Page Object Model (POM) design pattern, implements Data-Driven Testing (DDT), and ensures high test reliability through explicit waiting strategies and modular architecture.

---

### 📂 Folder Structure

```text
automation-project/
├── .env
├── package.json
├── playwright.config.ts
├── data/
│   └── testData.json
├── pages/
│   ├── BasePage.ts
│   └── GeneralPage.ts
├── tests/
│   └── general.spec.ts
└── utils/
    └── envUtils.ts
```

---

### --- Configuration & Dependencies

#### 1. `.env`
```env
BASE_URL=https://your-application-url.com
```

#### 2. `package.json`
```json
{
  "name": "playwright-automation",
  "version": "1.0.0",
  "devDependencies": {
    "@playwright/test": "^1.40.0",
    "@types/node": "^20.0.0",
    "typescript": "^5.0.0"
  },
  "scripts": {
    "test": "npx playwright test"
  }
}
```

#### 3. `playwright.config.ts`
```typescript
import { defineConfig, devices } from '@playwright/test';
import { EnvUtils } from './utils/envUtils';
import path from 'path';

const runId = new Date().getTime();

export default defineConfig({
  testDir: './tests',
  fullyParallel: false,
  workers: 1,
  retries: 0,
  reporter: [['html', { outputFolder: `playwright-report/run-${runId}` }]],
  globalTimeout: 180000,
  expect: { timeout: 60000 },
  outputDir: `test-results/run-${runId}`,
  use: {
    baseURL: EnvUtils.BASE_URL,
    actionTimeout: 50000,
    trace: 'on',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
  },
  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } }
  ],
});
```

#### 4. `utils/envUtils.ts`
```typescript
import * as dotenv from 'dotenv';
dotenv.config();

export class EnvUtils {
  public static readonly BASE_URL = process.env.BASE_URL || '';
}
```

---

### --- Page Object Model (POM)

#### 1. `pages/BasePage.ts`
```typescript
import { expect, Locator, Page } from '@playwright/test';

export abstract class BasePage {
  public readonly page: Page;

  constructor(page: Page) {
    this.page = page;
  }

  public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
    await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
  }
}
```

#### 2. `pages/GeneralPage.ts`
```typescript
import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

export class GeneralPage extends BasePage {
  public readonly nextButton: Locator;
  public readonly recordList: Locator;

  constructor(page: Page) {
    super(page);
    this.nextButton = page.getByRole('button', { name: /next/i });
    this.recordList = page.getByTestId('data-record-item');
  }

  public async clickNext(): Promise<void> {
    await this.nextButton.click();
  }

  public async verifyNewDataLoaded(previousCount: number): Promise<void> {
    await expect(this.recordList.first()).toBeVisible();
  }
}
```

---

### --- Test Implementation

#### 1. `data/testData.json`
