```typescript
import { test, expect, Page } from '@playwright/test';
import { GeneralPage } from '../pages/GeneralPage';
import { EnvUtils } from '../utils/envUtils';
import testData from '../data/testData.json';

test.describe('General Functionality Module', () => {
  let generalPage: GeneralPage;

  test.beforeEach(async ({ page }) => {
    generalPage = new GeneralPage(page);
    await page.goto(EnvUtils.BASE_URL);
  });

  testData.forEach((data) => {
    test(`${data.testCaseId} - ${data.description}`, async ({ page }, testInfo) => {
      // Step 1: Click the 'Next' button while on the first page
      await generalPage.clickNext();

      // Expected Result: The system dynamically loads and displays the next set of records
      await generalPage.verifyNewDataLoaded(data.expectedCount);

      const currentUrl = page.url();
      expect(currentUrl).toBeDefined();
    });
  });
});
```

