import { test, expect } from '@playwright/test';
import { LandingAuthenticationPagePage } from '../pages/LandingAuthenticationPagePage';
import { ApplicationDashboardNavigationPage } from '../pages/ApplicationDashboardNavigationPage';
import { WorkflowDetailsActionViewPage } from '../pages/WorkflowDetailsActionViewPage';

test.describe('Testlogin video Automated Flow - Playwright TypeScript Suite', () => {
  test('executes all verified sequential steps from walkthrough video', async ({ page }) => {
    const landingauthenticationpagePage = new LandingAuthenticationPagePage(page);
    const applicationdashboardnavigationPage = new ApplicationDashboardNavigationPage(page);
    const workflowdetailsactionviewPage = new WorkflowDetailsActionViewPage(page);

    // Navigate to initial application URL
    await landingauthenticationpagePage.navigate();

    // Step 1: Verify Application Home Page
    await landingauthenticationpagePage.verify_application_home_page();

    // Step 2: Fill Username / Mobile Number Field
    await landingauthenticationpagePage.fill_username___mobile_number_field('9876543210');

    // Step 3: Fill Password Field
    await landingauthenticationpagePage.fill_password_field('SecretPassword123!');

    // Step 4: Click Login to Dashboard Button
    await landingauthenticationpagePage.click_login_to_dashboard_button();

    // Step 5: Click Main Module Navigation Menu
    await applicationdashboardnavigationPage.click_main_module_navigation_menu();

    // Step 6: Click Action Trigger Button
    await workflowdetailsactionviewPage.click_action_trigger_button();

    // Step 7: Verify Workflow Verification View
    await workflowdetailsactionviewPage.verify_workflow_verification_view();

    // Verification check
    await expect(page).not.toHaveURL(/error/i);
  });
});
